args.old_string:
# Import the original devrig.sh commands for compatibility
source "$REPO/tools/devrig.sh" 2>/dev/null || {
  # Fallback to essential commands if import fails
  cmd_cert() {
    sudo tailscale cert --cert-file "$REPO/.certs/sf.crt" --key-file "$REPO/.certs/sf.key" "$HOST"
    sudo chown "$USER:$USER" "$REPO/.certs/sf.crt" "$REPO/.certs/sf.key"
    chmod 600 "$REPO/.certs/sf.key"
  }

  cmd_send() { ssh -o BatchMode=yes "$BENCH" "DISPLAY=:0 chromium --app='$(url send "$@")'"; }
  cmd_recv() { adb shell am start -a android.intent.action.VIEW -d "'$(url recv "$@")'"; }
  cmd_stop() { ssh "$BENCH" pkill -f sf-bench; adb shell am force-stop com.android.chrome; }
  cmd_shots() { ssh "$BENCH" "maim /tmp/bench.png"; scp "$BENCH:/tmp/bench.png" "$1"; adb exec-out screencap -p > "$2"; }
}

args.new_string:
case "${1:-}" in
  setup-check) run_setup_check ;;
  run-qualifying) shift; cmd_run_qualifying "$@" ;;
  thermal-baseline) cmd_thermal_baseline ;;
  cert) cmd_cert ;;
  serve) cmd_serve ;;
  send) shift; cmd_send "$@" ;;
  recv) shift; cmd_recv "$@" ;;
  shots) shift; cmd_shots "$@" ;;
  stats) cmd_stats ;;
  bstats) cmd_bench_stats ;;
  stop) cmd_stop ;;
  *)

